import{_ as e,o as a,c as r,a0 as o}from"./chunks/framework.DzvPB4Y-.js";const m=JSON.parse('{"title":"网络优化 Network","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/network/index.md","filePath":"zh-cn/frameworks/network/index.md"}'),l={name:"zh-cn/frameworks/network/index.md"};function i(d,t,n,h,c,s){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="网络优化-network" tabindex="-1">网络优化 Network <a class="header-anchor" href="#网络优化-network" aria-label="Permalink to &quot;网络优化 Network&quot;">​</a></h1><p>在有向网络中满足供需，遵守运输或处理容量，并最小化费用。之后可以增加网络建设、资源路径、结构与显式故障场景。不要把 Network 只理解为车辆路径。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>输入或输出</th></tr></thead><tbody><tr><td>拓扑</td><td>Node / Arc</td><td>稳定身份、端点和平行服务</td></tr><tr><td>商品与供需</td><td>Commodity / Balance</td><td>各商品的节点供需与计量单位</td></tr><tr><td>容量和费用</td><td>Capacity / Cost</td><td>弧及共享资源的上限、单价</td></tr><tr><td>流问题</td><td><code>FlowProblem</code></td><td>拓扑、商品、费用与资源配置</td></tr><tr><td>注册与提取</td><td><code>FlowContext</code></td><td>守恒、容量、费用表达式和流量结果</td></tr></tbody></table><p>整数步长表示计量粒度，不表示整单不可拆。不同商品共同占用资源时，需要明确物理量换算，不能把吨和件直接相加。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><p>独立流入口为 Kotlin <code>NetworkFlowApplicationService</code>、Rust <code>FlowApplicationService</code>。嵌入其他模型时使用 <code>FlowContext</code> 注册，不要再启动一个不共享变量的独立优化。</p><p>先学习流与容量，再扩展建设和韧性。VRPTW 的路线列、ESPPRC 和分支定价属于进阶路线。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>平行弧需要独立身份，不能只按起点/终点去重。</li><li>连通性不证明运输容量充足；建成总容量不等于增量容量。</li><li>显式韧性只保障给定场景，不能外推为对未知故障的普遍保证。</li><li>维修作业的时间、人员和日历属于 <a href="./../gantt/">Gantt</a>，不是 Network 自动决定的。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-flow.html">第一次网络流优化</a>，先检查守恒、费用与容量。</li><li>增加共享资源、容量等级、建设预算和一个故障场景，每次只改一类条件。</li><li>需要车辆路线时，继续到 <a href="/ospf/zh-cn/examples/framework-example5.html">VRPTW 综合案例</a>。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-network-scheduling/README_ch.md" target="_blank" rel="noreferrer">Kotlin 网络领域与独立入口</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-network-scheduling/README_ch.md" target="_blank" rel="noreferrer">Rust 网络领域与证明契约</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./business-scenario.html">共享资源、缺货与联合模型</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',17)])])}const p=e(l,[["render",i]]);export{m as __pageData,p as default};
